<div><label class="form-label" for="descricao">Descrição</label><textarea class="form-control" id="descricao" name="descricao" rows="6" minlength="20" maxlength="5000" required><?= e($row['descricao']??'') ?></textarea><small class="text-secondary">Explique o problema com pelo menos 20 caracteres.</small></div>
